<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useRoute} from 'vue-router'
import {workbenchApi,type ProjectWorkbench} from '../api'
import {errorMessage} from '../utils'
const pid=Number(useRoute().params.projectId),data=ref<ProjectWorkbench>(),loading=ref(false),error=ref('')
const base=`/projects/${pid}`
const configurationLabels={generation:'生成模型',embedding:'Embedding',rerank:'Rerank',judge:'Judge'}
const configPaths={generation:'/settings',embedding:'/settings/embedding',rerank:'/settings/rerank',judge:'/settings/judge'}
const counts=computed(()=>data.value?[{label:'需求',value:data.value.requirements,detail:`有效确认 ${data.value.confirmed_requirements} 条`,path:base+'/requirements'},
 {label:'用例草稿',value:data.value.drafts,detail:`待评审 ${data.value.review_counts.pending||0} 条`,path:base+'/requirements'},
 {label:'已采纳用例',value:data.value.review_counts.accepted||0,detail:`驳回 ${data.value.review_counts.rejected||0} 条`,path:base+'/testcases'},
 {label:'知识文档',value:data.value.knowledge_documents,detail:`有效分块 ${data.value.knowledge_chunks} 个`,path:base+'/knowledge'},
 {label:'人工执行任务',value:Object.values(data.value.execution.task_counts).reduce((a,b)=>a+b,0),detail:`记录中 ${data.value.execution.task_counts.open||0} · 已结束 ${data.value.execution.task_counts.completed||0}`,path:base+'/execution-tasks'},
 {label:'独立评测样本',value:data.value.evaluation.samples,detail:`运行 ${Object.values(data.value.evaluation.runs).reduce((a,b)=>a+b,0)} 次`,path:base+'/evaluations'}]:[])
async function load(){if(loading.value)return;loading.value=true;error.value='';try{data.value=await workbenchApi.get(pid)}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
onMounted(load)
</script>
<template><main><router-link to="/" class="back-link">← 项目列表</router-link><div class="page-heading"><div><div class="eyebrow">PROJECT WORKBENCH</div><h1>{{data?.name||'项目'}} · 工作台</h1><p>按实际记录查看进度，再选择下一步操作。</p></div><el-button :loading="loading" @click="load">刷新工作台</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-skeleton v-if="loading&&!data" :rows="6" animated/>
<template v-if="data"><section class="next-action project-panel"><div><span class="eyebrow">当前下一步</span><h2>{{data.next_action.title}}</h2><p>{{data.next_action.detail}}</p></div><router-link :to="data.next_action.path" class="next-link">去处理 →</router-link></section><p class="field-help">本页仅读取本地数据，不自动创建需求、运行模型或连接 MCP。</p><div class="workbench-counts"><router-link v-for="item in counts" :key="item.label" :to="item.path" class="count-card"><span>{{item.label}}</span><strong>{{item.value}}</strong><small>{{item.detail}}</small></router-link></div>
<section class="project-panel workbench-section"><h2>生成与质量记录</h2><div class="workbench-facts"><span>有效确认功能点 {{data.current_confirmed_features}}</span><span>有当前版本生成记录 {{data.current_features_with_generation}}</span><span>生成批次 {{data.generation_batches}}（真实 {{data.generation_sources.real||0}} / Mock {{data.generation_sources.mock||0}}）</span><span>Judge 报告 {{Object.values(data.judge_counts).reduce((a,b)=>a+b,0)}}（成功 {{data.judge_counts.succeeded||0}} / 失败 {{data.judge_counts.failed||0}}）</span></div><p class="field-help">{{data.coverage_note}} {{data.judge_note}}</p><details><summary>生成与向量任务状态</summary><pre>{{JSON.stringify({生成任务:data.generation_tasks,向量任务:data.vector_tasks},null,2)}}</pre></details></section>
<section class="project-panel workbench-section"><div class="workbench-title"><h2>人工执行记录</h2><router-link :to="base+'/execution-tasks'">进入测试执行 →</router-link></div><div class="workbench-facts"><span>已记录 {{data.execution.item_stats.recorded}} / {{data.execution.item_stats.total}}</span><span>通过 {{data.execution.item_stats.passed}}</span><span>失败 {{data.execution.item_stats.failed}}</span><span>阻塞 {{data.execution.item_stats.blocked}}</span><span>未执行 {{data.execution.item_stats.not_run}}</span><span>通过率 {{data.execution.item_stats.pass_rate===null?'—':data.execution.item_stats.pass_rate+'%'}}</span></div><p class="field-help">{{data.execution.note}}</p><p v-if="!data.execution.item_stats.total">尚无人工执行条目，暂无实测记录。</p></section>
<section class="project-panel workbench-section"><div class="workbench-title"><h2>离线评测</h2><router-link :to="base+'/evaluations'">查看独立样本与运行 →</router-link></div><div class="workbench-facts"><span>样本 {{data.evaluation.samples}}</span><span>真实模式运行 {{data.evaluation.real_runs}}</span><span>Mock 运行 {{data.evaluation.mock_runs}}</span><span>队列处理结束 {{data.evaluation.runs.completed||0}}</span><span>中断 {{data.evaluation.runs.interrupted||0}}</span></div><p class="field-help">运行模式和完成数不等于质量结论。需核对样本明细、生成成功率、Judge 完成率及共同样本分母；词面召回不是语义覆盖率。</p></section>
<section class="project-panel workbench-section"><h2>配置准备情况</h2><p class="field-help">仅显示已保存字段，不自动测试连接或验证 Key、权限、额度。</p><div class="workbench-configs"><article v-for="(label,key) in configurationLabels" :key="key"><h3>{{label}}</h3><el-tag :type="data.configuration[key].mode==='mock'?'warning':'info'">{{data.configuration[key].ready?(data.configuration[key].mode==='mock'?'已保存 Mock 配置':'已保存真实配置'):'待完成配置'}}</el-tag><p v-if="key==='judge'" class="field-help">{{data.configuration[key].source==='generation'?'默认复用生成模型':'使用独立 Judge 配置'}}</p><router-link :to="configPaths[key]">查看设置 →</router-link></article></div><div class="workbench-title"><h3>MCP 工具</h3><router-link :to="base+'/mcp'">查看本项目授权 →</router-link></div><p>绑定 {{data.mcp.bindings}} 个服务 · 当前版本绑定 {{data.mcp.current_bindings}} 个 · 已启用工具 {{data.mcp.enabled_tools}} 个</p><p class="field-help">{{data.mcp.note}} 外部数据范围由服务账号权限决定。</p></section><p v-for="note in data.notes" :key="note" class="field-help">{{note}}</p></template></main></template>
<style scoped>.next-action{padding:24px;display:flex;justify-content:space-between;align-items:center;gap:24px}.next-action h2{margin:8px 0}.next-action p{line-height:1.8;margin-bottom:0}.next-link{white-space:nowrap;border-radius:8px;padding:12px 20px;background:#315b96;color:white;text-decoration:none}.workbench-counts{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin:24px 0}.count-card{display:flex;flex-direction:column;gap:10px;padding:20px;background:white;border:1px solid #e1e7ef;border-radius:10px;text-decoration:none;color:#46546a}.count-card strong{font-size:30px;color:#23344d}.count-card small{color:#7d8ba0}.count-card:hover{border-color:#315b96}.workbench-section{padding:22px;margin:20px 0}.workbench-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.workbench-facts{display:flex;gap:12px 24px;flex-wrap:wrap;line-height:2}.workbench-configs{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:20px}.workbench-configs article{display:flex;flex-direction:column;align-items:flex-start;gap:12px;padding:12px;border:1px solid #e4eaf1;border-radius:8px}.workbench-configs h3{margin:0}pre{white-space:pre-wrap}@media(max-width:700px){.next-action{align-items:flex-start;flex-direction:column}}</style>
